static int depth(Node node) {
    if (node == null)
        return 0;                       // guard clauses, no else branch
    if (node.isLeaf())
        return 1;

    int left = depth(node.left);
    int right = depth(node.right);
    return 1 + Math.max(left, right);   // body stays at one level
}
